  "models.long_horizon_astra_variant_for_multi_day_tasks": "Вариант Astra для многодневных задач. ID не проверен и ещё не указан на странице моделей OpenAI; нужен codex CLI ≥ 0.153, как для Astra.",
  "models.recommended_default_near_astra_performance_for_complex_coding": "По умолчанию — близкая к Astra производительность в сложной разработке и агентных задачах по цене GPT-6 Sol. Обновление GPT-6 Sol. Нужен codex CLI ≥ 0.159; старые версии возвращают 400, ошибочно указывая на аккаунт ChatGPT.",
  "models.previous_sol_still_offered_gpt_6_1_sol": "Предыдущая Sol доступна; GPT-6.1 Sol — её обновление. Нужен codex CLI ≥ 0.155; старые версии возвращают 400, ошибочно указывая на аккаунт ChatGPT.",
  "models.fastest_lowest_cost_gpt_6_for_focused_high": "Самая быстрая и дешёвая GPT-6 для узких массовых задач; заменяет GPT-5.6 Luna. Нужен codex CLI ≥ 0.155; старые версии возвращают 400, ошибочно указывая на аккаунт ChatGPT.",
  "models.cybersecurity_tuned_gpt_5_6_requires_openai_daybreak": "GPT-5.6 для кибербезопасности. Требуется одобрение OpenAI Daybreak с API-ключом; планы ChatGPT не поддерживаются.",
  "models.previous_generation_flagship_superseded_by_gpt_6_1": "Флагман предыдущего поколения, заменён GPT-6.1 Sol; ещё работает с планами ChatGPT.",
