  "models.previous_generation_model_works_on_chatgpt_plans_codex": "Модель предыдущего поколения работает с планами ChatGPT; Codex прекращает поддержку 2026-10-14 (перейдите на GPT-6.1 Sol).",
  "models.requires_an_api_key_account_rejected_on_chatgpt": "Требуется аккаунт с API-ключом; планы ChatGPT не поддерживаются.",
