  "models.propose_only_cursor_cannot_execute_unapproved_actions_headlessly": "Только предложения — Cursor не выполняет неодобренные действия без интерактивного режима.",
  "models.newest_flagship_ga_2026_10_13_google_s": "Новый флагман (GA 2026-10-13) — мощнейшая модель Google для сложной разработки, агентных задач, математики и науки. Нужен платный ключ Gemini API или Agent Platform (не бесплатный API). Gemini CLI больше не обслуживает входы Google AI Pro/Ultra; для них используйте Antigravity. До регистрации ID в Gemini CLI используется средний уровень рассуждений Google.",
  "models.recommended_default_current_flagship_google_s_successor_to": "По умолчанию — текущий флагман Google, преемник выведенной из эксплуатации 3 Pro preview.",
