  "models.hands_off_default_disables_fx_s_permission_checks": "По умолчанию без запросов — полностью отключает проверки разрешений fx, вызовы инструментов не задерживаются. В fx 0.0.8 это --full-access / /permissions full-access (сохраняется в 0.0.10); yolo остаётся псевдонимом и хранимым ID agetor.",
