  "settings.listing_creating_merging_closing_drafting_and_auto_90149a": "Просмотр, создание, слияние, закрытие, черновики и автослияние PR; проверки, комментарии к строкам, предложения и обсуждения проверки.",
  "settings.pick_a_name_and_expiration_set_resource_62fbbe": "Укажите имя и срок действия. В Resource owner выберите личный аккаунт либо организацию, которой принадлежат нужные репозитории.",
