  "settings.if_the_token_needs_to_reach_an_618f64": "Для организации с SAML SSO откройте меню Configure SSO у токена и разрешите доступ к организации.",
  "settings.mergeability_hasn_t_been_verified_merging_will_efe247": "Возможность слияния не проверена — будет предпринята попытка с текущими данными",
