  "settings.out_of_date_with_the_base_branch_066527": "Исходная ветка отстаёт от базовой",
  "settings.conflicts_must_be_resolved_before_merging_e71d55": "Перед слиянием нужно разрешить конфликты",
  "settings.blocked_by_required_reviews_or_checks_256f24": "Заблокировано обязательными проверками кода или CI",
  "settings.draft_mark_ready_for_review_to_merge_b2c139": "Черновик — отметьте готовым к проверке для слияния",
  "settings.wait_for_the_import_to_finish_then_7f2dfb": "Дождитесь завершения импорта и перетащите файл снова.",
  "settings.under_api_tokens_click_create_api_token_921140": "В API tokens нажмите Create API token with scopes (не обычный Create API token без областей доступа — он подходит Jira/Confluence, но отклоняется api.bitbucket.org). Задайте имя, выберите Bitbucket и отметьте области ниже.",
  "settings.back_in_the_git_host_tokens_section_91fba9": "В разделе токенов Git-хостов введите хост (bitbucket.org или SSH-псевдоним), а в поле токена — email Atlassian, двоеточие и API token, например jane@example.com:ATATT3x…. Пароли приложений Bitbucket выведены из эксплуатации 2026-06-09; замените их токеном этого формата.",
  "settings.listing_repos_reading_diffs_commit_statuses_and_edc5b7": "Просмотр репозиториев, изменений, статусов коммитов и слияние PR.",
  "settings.listing_creating_merging_declining_and_reviewing_prs_80e6a6": "Просмотр, создание, слияние, отклонение и проверка PR; комментарии к PR и строкам; поиск конфликтов слияния.",
  "settings.the_repository_issue_tracker_listing_creating_updating_5184d8": "Задачи репозитория — просмотр, создание, обновление и комментирование.",
  "settings.resolving_the_signed_in_account_used_for_9fb471": "Определение текущего аккаунта для фильтров «назначено мне» / «создано мной».",
  "settings.from_your_gitlab_avatar_go_to_edit_b86358": "В меню аватара GitLab выберите Edit profile, затем Access tokens слева.",
  "settings.click_create_personal_access_token_and_copy_a9a905": "Нажмите Create personal access token и скопируйте его — он показывается один раз. В разделе токенов Git-хостов введите хост (gitlab.com или SSH-псевдоним) и токен.",
